namespace ZapretManager {
public class HistoryForm:Form {
 public HistoryForm(Action<string> restore){Text="История настроек";Size=new Size(740,490);StartPosition=FormStartPosition.CenterParent;Padding=new Padding(18);var files=Convenience.History();var list=new ListBox {Dock=DockStyle.Fill};list.Items.AddRange(files.Select(Path.GetFileName).ToArray());var hint=new Label {Text="Выберите копию. Перед восстановлением текущие настройки тоже сохранятся.",Dock=DockStyle.Top,Height=50};var button=new Button {Text="Восстановить выбранную копию",Dock=DockStyle.Bottom,Height=45};button.Click+=(s,e)=>{if(list.SelectedIndex<0)return;if(MessageBox.Show(this,"Восстановить настройки и состояние службы из выбранной копии?","История",MessageBoxButtons.YesNo,MessageBoxIcon.Question)!=DialogResult.Yes)return;string path=files[list.SelectedIndex];Close();restore(path);};Controls.Add(list);Controls.Add(hint);Controls.Add(button);UiTheme.Apply(this);}
}
public class PreferencesForm:Form {
 bool saving;
 public PreferencesForm(Action saved){Text="Настройки запуска и трея";Size=new Size(670,590);MinimumSize=Size;StartPosition=FormStartPosition.CenterParent;Padding=new Padding(24);var p=Convenience.Preferences();var panel=new FlowLayoutPanel {Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false,AutoScroll=true};var start=new CheckBox {Text="Запускать свёрнутым",Checked=p.StartInTray,AutoSize=true};var auto=new CheckBox {Text="Запускать панель при входе в Windows",Checked=p.PanelAutoStart,AutoSize=true};var service=new CheckBox {Text="Автозапуск с Windows — служба Zaper",Checked=Core.Load().AutoStart,AutoSize=true};var notifications=new CheckBox {Text="Уведомлять об ошибках",Checked=p.NotifyErrors,AutoSize=true};panel.Controls.AddRange(new Control[]{start,new Label {Text="При следующем запуске окно останется скрытым; открыть его можно значком в трее.",Width=590,Height=55},auto,new Label {Text="Открывает панель в трее при входе в учётную запись Windows.",Width=590,Height=45},service,new Label {Text="Автоматически запускает обработку трафика при загрузке Windows. Работает независимо от запуска панели.",Width=590,Height=55},notifications,new Label {Text="Показывает уведомление Windows при ошибке операции. Подробности сохраняются в журнале.",Width=590,Height=55}});var button=new Button {Text="Сохранить",Width=160,Height=44};button.Click+=async(s,e)=>{if(saving||!Core.OperationGate.Wait(0)){MessageBox.Show(this,"Дождитесь завершения текущей операции.",Text);return;}saving=true;panel.Enabled=false;var selected=new UiPreferences {StartInTray=start.Checked,PanelAutoStart=auto.Checked,NotifyErrors=notifications.Checked};bool startup=service.Checked;bool success=false;try{await Task.Run(()=>Convenience.SaveLaunchSettings(selected,startup));saved();success=true;}catch(Exception ex){MessageBox.Show(this,ex.Message,"Не удалось сохранить");}finally{saving=false;panel.Enabled=true;Core.OperationGate.Release();}if(success)Close();};FormClosing+=(s,e)=>{if(saving)e.Cancel=true;};panel.Controls.Add(button);Controls.Add(panel);UiTheme.Apply(this);UiTheme.Primary(button);}

}
public class AppPicker:Form {
 readonly ListView list=new ListView {Dock=DockStyle.Fill,View=View.Details,HeaderStyle=ColumnHeaderStyle.None,CheckBoxes=true,FullRowSelect=true,HideSelection=false,MultiSelect=false};readonly ImageList icons=new ImageList {ImageSize=new Size(24,24),ColorDepth=ColorDepth.Depth32Bit};readonly Dictionary<string,int> iconIndex=new Dictionary<string,int>(StringComparer.OrdinalIgnoreCase);readonly List<Image> iconImages=new List<Image>();readonly TextBox search=new TextBox {Dock=DockStyle.Top};readonly Label info=new Label {Dock=DockStyle.Bottom,Height=45};readonly HashSet<string> marked=new HashSet<string>(StringComparer.OrdinalIgnoreCase);bool filtering;readonly SortedSet<string> paths=new SortedSet<string>(StringComparer.OrdinalIgnoreCase);
 public AppPicker(Action<string[]> selected){Text="Выбрать приложения для исключений";Size=new Size(900,610);MinimumSize=new Size(700,450);StartPosition=FormStartPosition.CenterParent;Padding=new Padding(18);list.Columns.Add("Приложение",800);list.SmallImageList=icons;list.Resize+=(s,e)=>list.Columns[0].Width=Math.Max(300,list.ClientSize.Width-6);var add=new Button {Text="Добавить выбранные",Dock=DockStyle.Bottom,Height=46};var header=new Label {Text="Поиск по названию или пути. Показаны найденные EXE установленных и запущенных приложений.",Dock=DockStyle.Top,Height=52};Controls.Add(list);Controls.Add(search);Controls.Add(header);Controls.Add(info);Controls.Add(add);UiTheme.Apply(this);list.BackColor=UiTheme.Surface;list.ForeColor=UiTheme.Text;list.BorderStyle=BorderStyle.None;search.TextChanged+=(s,e)=>Filter();list.ItemChecked+=(s,e)=>{if(filtering)return;string path=(string)e.Item.Tag;if(e.Item.Checked)marked.Add(path);else marked.Remove(path);};add.Click+=(s,e)=>{selected(marked.ToArray());Close();};Shown+=(s,e)=>LoadApps();FormClosed+=(s,e)=>{icons.Dispose();foreach(var image in iconImages)image.Dispose();};}
 int IconFor(string path){int index;if(iconIndex.TryGetValue(path,out index))return index;Image image;try{using(var icon=Icon.ExtractAssociatedIcon(path))image=(icon??SystemIcons.Application).ToBitmap();}catch{image=SystemIcons.Application.ToBitmap();}iconImages.Add(image);index=icons.Images.Count;icons.Images.Add(image);iconIndex[path]=index;return index;}
 public bool TestIconsAndSelection(){if(list.Items.Count==0)return false;var first=list.Items[0];string path=(string)first.Tag;bool hasIcon=first.ImageIndex>=0&&first.ImageIndex<icons.Images.Count;first.Checked=true;search.Text=Path.GetFileName(path);search.Text="__no_app_matches_this__";search.Text="";var item=list.Items.Cast<ListViewItem>().FirstOrDefault(i=>(string)i.Tag==path);bool retained=item!=null&&item.Checked&&marked.Contains(path);if(item!=null)item.Checked=false;return hasIcon&&retained;}
 void LoadApps(){foreach(var process in Process.GetProcesses()){using(process){try{string path=process.MainModule.FileName;if(File.Exists(path))paths.Add(path);}catch{}}}foreach(var hive in new[]{RegistryHive.LocalMachine,RegistryHive.CurrentUser})foreach(var view in new[]{RegistryView.Registry64,RegistryView.Registry32}){using(var root=RegistryKey.OpenBaseKey(hive,view))foreach(var key in new[]{@"SOFTWARE\Microsoft\Windows\CurrentVersion\App Paths",@"SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall"})using(var branch=root.OpenSubKey(key)){if(branch==null)continue;foreach(string name in branch.GetSubKeyNames())using(var app=branch.OpenSubKey(name)){if(app==null)continue;string value=Convert.ToString(app.GetValue(key.EndsWith("App Paths")?"":"DisplayIcon"));if(value.StartsWith("\"")){int end=value.IndexOf('"',1);if(end>1)value=value.Substring(1,end-1);}else{int comma=value.LastIndexOf(',');if(comma>0)value=value.Substring(0,comma);}value=Environment.ExpandEnvironmentVariables(value);if(value.EndsWith(".exe",StringComparison.OrdinalIgnoreCase)&&File.Exists(value))paths.Add(Path.GetFullPath(value));}}}Filter();}
 void Filter(){filtering=true;list.BeginUpdate();try{list.Items.Clear();foreach(string path in paths.Where(p=>p.IndexOf(search.Text,StringComparison.OrdinalIgnoreCase)>=0)){var item=new ListViewItem(path,IconFor(path)) {Tag=path,Checked=marked.Contains(path),ToolTipText=path};list.Items.Add(item);}}finally{list.EndUpdate();filtering=false;}info.Text="Найдено: "+paths.Count+". Если нужного EXE нет, используйте «Добавить EXE».";}

}
public class LatencyPanel:UserControl {
 readonly TextBox target=new TextBox {Text="1.1.1.1",Width=180};readonly ComboBox adapters=new ComboBox {Width=300,DropDownStyle=ComboBoxStyle.DropDownList};readonly Label info=new Label {Dock=DockStyle.Bottom,Height=65};readonly Chart chart=new Chart {Dock=DockStyle.Fill};readonly System.Windows.Forms.Timer timer=new System.Windows.Forms.Timer {Interval=1000};readonly List<double> samples=new List<double>();NetworkInterface[] interfaces;bool pending,closed;int lost,total,generation;long previousReceived,previousSent;DateTime previousTime;Ping current;
 public LatencyPanel(){Size=new Size(800,330);var controls=new FlowLayoutPanel {Dock=DockStyle.Top,AutoSize=true,MaximumSize=new Size(0,125),Padding=new Padding(8)};controls.Controls.Add(new Label {Text="Адрес для пинга",Width=145,Height=35});controls.Controls.Add(target);controls.Controls.Add(adapters);controls.Controls.Add(new Label {Text="ICMP отражает доступность выбранного узла, а не допуск в матч. Скорость показана для выбранного адаптера.",Width=660,Height=40});var routes=Core.InternetInterfaces();interfaces=NetworkInterface.GetAllNetworkInterfaces().Where(n=>n.OperationalStatus==OperationalStatus.Up&&n.NetworkInterfaceType!=NetworkInterfaceType.Loopback).OrderByDescending(n=>{try{return routes.Contains(n.GetIPProperties().GetIPv4Properties().Index);}catch{return false;}}).ToArray();adapters.Items.AddRange(interfaces.Select(n=>n.Name).ToArray());if(interfaces.Length>0)adapters.SelectedIndex=0;chart.ChartAreas.Add(new ChartArea("Network"));chart.Series.Add(new Series("Задержка, мс") {ChartType=SeriesChartType.Line,BorderWidth=3,Color=UiTheme.Accent});var area=chart.ChartAreas[0];chart.BackColor=area.BackColor=UiTheme.Background;area.AxisX.LabelStyle.ForeColor=area.AxisY.LabelStyle.ForeColor=UiTheme.Text;area.AxisX.MajorGrid.LineColor=area.AxisY.MajorGrid.LineColor=UiTheme.Surface;area.AxisY.Title="мс";area.AxisY.TitleForeColor=UiTheme.Text;Controls.Add(chart);Controls.Add(controls);Controls.Add(info);UiTheme.Apply(this);timer.Tick+=async(s,e)=>await Sample();VisibleChanged+=(s,e)=>{if(Visible)timer.Start();else timer.Stop();};Disposed+=(s,e)=>{closed=true;timer.Stop();timer.Dispose();if(current!=null)try{current.SendAsyncCancel();}catch{}};target.TextChanged+=(s,e)=>Reset();adapters.SelectedIndexChanged+=(s,e)=>Reset();}
 public async Task<bool> TestLocal(){timer.Stop();target.Text="127.0.0.1";Reset();await Sample();await Sample();return total==2&&lost==0&&chart.Series[0].Points.Count==2;}
 void Reset(){generation++;samples.Clear();lost=total=0;previousTime=default(DateTime);chart.Series[0].Points.Clear();}
 async Task Sample(){if(pending||closed)return;System.Net.IPAddress ip;if(!System.Net.IPAddress.TryParse(target.Text,out ip)){info.Text="Введите IP узла или сервера, например 1.1.1.1.";return;}pending=true;int requestedGeneration=generation;try{double latency=-1;using(var ping=new Ping()){current=ping;try{var response=await ping.SendPingAsync(ip,800);if(response.Status==IPStatus.Success)latency=response.RoundtripTime;}catch{}finally{current=null;}}if(closed||requestedGeneration!=generation)return;total++;if(latency<0)lost++;else samples.Add(latency);var points=chart.Series[0].Points;points.Add(new DataPoint(total,Math.Max(0,latency)) {IsEmpty=latency<0});if(points.Count>120)points.RemoveAt(0);if(samples.Count>120)samples.RemoveAt(0);double down=0,up=0;if(adapters.SelectedIndex>=0){var stats=interfaces[adapters.SelectedIndex].GetIPStatistics();var now=DateTime.UtcNow;if(previousTime!=default(DateTime)){double dt=(now-previousTime).TotalSeconds;down=Math.Max(0,stats.BytesReceived-previousReceived)*8/dt/1000000;up=Math.Max(0,stats.BytesSent-previousSent)*8/dt/1000000;}previousTime=now;previousReceived=stats.BytesReceived;previousSent=stats.BytesSent;}double jitter=samples.Count<2?0:samples.Zip(samples.Skip(1),(a,b)=>Math.Abs(a-b)).Average();info.Text="Пинг: "+(latency<0?"нет ответа":latency+" мс")+"  |  Средний: "+(samples.Count==0?"—":samples.Average().ToString("0.0"))+" мс  |  Колебания: "+jitter.ToString("0.0")+" мс  |  ICMP без ответа: "+lost+"/"+total+"\nПолучение: "+down.ToString("0.00")+" Мбит/с  |  Отправка: "+up.ToString("0.00")+" Мбит/с";}catch(Exception e){if(!closed)info.Text=e.Message;}finally{pending=false;}}
}
public class LatencyForm:Form {
 readonly LatencyPanel panel=new LatencyPanel {Dock=DockStyle.Fill};
 public LatencyForm(){Text="Задержка и нагрузка сети";Size=new Size(940,600);StartPosition=FormStartPosition.CenterParent;Controls.Add(panel);UiTheme.Apply(this);}
 public Task<bool> TestLocal(){return panel.TestLocal();}
}
}
